import{_ as n,l,o as e,c as i,v as t,p as s,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"局部投影","description":"","frontmatter":{"title":"局部投影","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/local-projections.md","filePath":"econ/local-projections.md","lastUpdated":1789023840000}'),c={name:"econ/local-projections.md"};function _(A,a,E,m,P,R){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="局部投影" tabindex="-1">局部投影 <a class="header-anchor" href="#局部投影" aria-label="Permalink to &quot;局部投影&quot;">​</a></h1><div class="epigraph"><p>每一地平线单独回归，不必先估一个套牢所有 $h$ 的 VAR；识别仍然要来自别处。</p><footer>—— Jordà, Estimation and Inference of Impulse Responses by Local Projections, AER 2005</footer></div><p><a href="/econ/svar-identification">上一课</a>用 VAR 的结构冲击生成所有地平线的 IRF。本课缺口是<strong>换估计器</strong>：局部投影（LP）把 \\(y_{t+h}\\) 直接投到冲击或工具上。不重写 \\(A_0\\) 的全部菜单，也不宣称 LP 免除识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VAR 的 IRF 是迭代：\\(C_h\\) 由同伴矩阵的幂给出，设定误差会随 \\(h\\) 累积。Jordà：对每个 \\(h\\) 估计</p> \\[y_{t+h}=\\alpha_h+\\beta_h\\varepsilon_t+\\gamma_h(L)X_t+u_{t+h}, \\]<p>\\(\\beta_h\\) 就是该地平线的脉冲。\\(\\varepsilon_t\\) 仍须是结构的：来自 SVAR、来自叙事、来自高频工具。缺口是把「IRF 的估计」从「VAR 设定」里拆出来，而不是再发明一种冲击。</p><p><span class="marginnote">Jordà, <em>AER</em> 95(1), 2005, 161–182。Plagborg-Møller and Wolf：在线性、正确设定且滞后足够时，LP 与 VAR 的 IRF 渐近谈的是同一对象，差别在有限样本偏差–方差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冲击已知时，LP 是一串 OLS（或 IV）。冲击要估计时，先做识别步骤，再投影。推断：重叠地平线使 \\(u_{t+h}\\) 序列相关，用 Newey–West 或滞后增广（Rambachan–Shephard、Montiel Olea 等讨论）。平滑 LP 把相邻 \\(h\\) 的 \\(\\beta_h\\) 借强度，回到一点 VAR 的味道。非线性：把状态（衰退、ZLB、债务高）放进交互，LP 比 VAR 更容易写成状态依存 IRF。</p>',10)),(e(),s(d,null,{default:o(()=>[p(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E8%AF%86%E5%88%AB%E5%BE%97%E5%88%B0%20%CE%B5%20%E6%88%96%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20LP%5B%22%E5%90%84%20h%20%E7%9A%84%E5%9B%9E%E5%BD%92%22%5D%0A%20%20LP%20--%3E%20IRF%5B%22%CE%B2_h%20%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20VAR%5B%22VAR%20%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20IRF2%5B%22%E5%90%8C%E4%BC%B4%E7%9F%A9%E9%98%B5%E5%B9%82%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>财政乘数、货币脉冲的近期文献大量用 LP，正是因为状态依存与较少的动态套牢。识别差时，LP 只是更灵活地报错。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是避免用错误的 VAR 动态去外推远地平线。代价是方差大、曲线毛。VAR 是收缩：所有 \\(h\\) 共享参数。选择不是哲学，是偏差–方差。两者都要求条件均值线性或你已经把非线性写进回归。预期：若冲击被预见，无论 LP 还是 VAR 都会在 \\(t\\) 之前动——新闻冲击课再处理。</p><p>与 DSGE：LP 的 \\(\\beta_h\\) 可当要匹配的半结构靶（Christiano–Eichenbaum–Evans 传统的 IRF 匹配），参数化仍回校准或估计课。</p><p><span class="marginnote">识别与估计分工：Stock–Watson 的外部工具可以进 SVAR，也可以进 LP-IV。后课叙事与高频，是工具的来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供新的冲击序列。不把 LP 写成「比结构模型更真」。面板 LP、区域乘数（Nakamura–Steinsson）是同一估计器的另一数据，本课只钉时间序列宏观。微观结构的脉冲（订单流）不在本栏。</p><p>后课默认：IRF 可用 VAR 或 LP 估；识别另给。下一课：叙事日期与高频意外如何提供那条识别。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LP：每地平线回归，少套牢动态，多方差。</li><li>识别不因 LP 而消失。</li><li>线性正确设定下，与 VAR 谈同一 IRF。</li><li>出处：Jordà, <em>AER</em> 2005。</li></ul>',10))])}const V=n(c,[["render",_]]);export{u as __pageData,V as default};
